basic.css:
/* BeeRus card styles - generated from the Anki Studio settings page */
html { font-size: 28px; }
.mobile { font-size: 28px; }
.card { font-family: "Arial Greek", Arial, sans-serif; font-size: 1rem; line-height: 1.35; text-align: center; margin: 15px 15px 0; padding-bottom: 1em; }
/* day mode */
.card { color: #000000; background-color: #D1CFCE; }
.cloze { font-weight: bold; color: #0000FF; }
#extra { font-style: italic; font-size: 1rem; color: #000080; margin-top: 1rem; }
/* night mode */
.nightMode.card, .night_mode .card { color: #FFFAFA !important; background-color: #272828 !important; }
.nightMode .cloze, .night_mode .cloze { color: #4297F9 !important; }
.nightMode #extra, .night_mode #extra { color: #FF00FF; }
/* bold / underline / italic keep the text colour (they carry meaning, not colour) */
b, u, i { color: inherit; }
hr { opacity: .7; }
img { max-width: 85%; max-height: 100%; }
#extra img { max-width: 85%; min-width: 30%; }
ul, ol { display: inline-block; max-width: 50%; padding-left: 40px; margin: auto; text-align: left; }
.mobile ul, .mobile ol, .mobile img { max-width: 100%; }
.mnemonics { display: inline-block; text-align: left; }
.centerbox { text-align: center; }
a:not([href]), a[href^="javascript:"] { text-decoration: none; color: inherit; }
table { border-collapse: collapse; margin: 8px auto; }
td, th { border: 1px solid #888; padding: 4px 9px; text-align: left; vertical-align: top; }
th { font-weight: bold; background: rgba(128, 128, 128, .18); }
blockquote { margin: 6px auto; padding: 2px 12px; border-left: 3px solid #888; text-align: left; display: inline-block; }
code { font-family: monospace; background: rgba(128, 128, 128, .2); padding: 0 4px; border-radius: 3px; }

#bpills { margin: 1.1rem auto 0; display: flex; flex-direction: column; align-items: center; gap: .5rem; font-size: 0.600rem; --ics: 1.25; font-style: normal; text-align: center; }
.bpill { max-width: 96%; }
.bpill > summary { list-style: none; cursor: pointer; display: inline-flex; align-items: center; gap: .45em; padding: .34em 1em; border-radius: 999px; font-weight: 700; font-family: Arial, sans-serif; line-height: 1.2; letter-spacing: .01em; user-select: none; transition: filter .12s, transform .08s; background: linear-gradient(var(--bp), var(--bp)); color: #fff; padding-left: .45em; box-shadow: 0 1px 3px rgba(0,0,0,.35); }
.bpill > summary:hover { filter: brightness(1.08); }
.bpill > summary:active { transform: scale(.97); }
.bpill > summary::-webkit-details-marker { display: none; }
.bpill > summary::marker { content: ""; }
.bpill > summary::after { content: "\25BE"; font-size: .85em; opacity: .85; transition: transform .15s; }
.bpill[open] > summary::after { transform: rotate(180deg); }
.bpill-ic { display: inline-block; width: calc(1.2em * var(--ics, 1)); height: calc(1.2em * var(--ics, 1)); background: center / contain no-repeat; }
.bpill-em { font-size: calc(1.1em * var(--ics, 1)); line-height: 1; }
.bpill-body { margin-top: .55rem; padding: .45rem .7rem; border-radius: .55em; border: 1px solid rgba(128,128,128,.35); border-left: 4px solid var(--bp); background: rgba(128,128,128,.1); font-size: .72rem; line-height: 1.4; text-align: center; }
.bpill-body img { max-width: 100%; height: auto; border-radius: .3em; }
.bs-bubble .bpill-em, .bs-bubble .bpill-ic { background-color: #fff; border-radius: 50%; display: inline-grid; place-items: center; overflow: hidden; }
.bs-bubble .bpill-em { font-size: calc(.95em * var(--ics, 1)); width: 1.85em; height: 1.85em; }
.bs-bubble .bpill-ic { width: calc(1.85em * var(--ics, 1)); height: calc(1.85em * var(--ics, 1)); background-size: cover; }
.bpill-1 { --bp: #3B82F6; --bpl: #72a5f9; --bpd: #295bac; --bpt: #3B82F62E; }
.bpill-2 { --bp: #10B981; --bpl: #53cda4; --bpd: #0b825a; --bpt: #10B9812E; }
.bpill-3 { --bp: #F59E0B; --bpl: #f8b94f; --bpd: #ac6f08; --bpt: #F59E0B2E; }
.bpill-4 { --bp: #A855F7; --bpl: #c085f9; --bpd: #763bad; --bpt: #A855F72E; }

